mapper.select:
select t.type_value, d.alarmLevel, d.alarmLevelName
from sys_alarm_type_level t
         LEFT JOIN
     (SELECT DICT_VALUE AS alarmLevel, DICT_LABEL AS alarmLevelName FROM sys_dict_data WHERE DICT_TYPE = 'alarm_level') d
     ON t.alarm_level = d.alarmLevel
where t.type_value = #{body.typeValue}
  and t.tenant_id = #{body.tenantId}
  and t.industry_code = #{body.industryCode}
  and t.delete_flag = '0'

mapper.update:
update sys_alarm_type_level
set alarm_level = #{body.alarmLevel}, modifier = #{body.modifier}, update_time = #{body.updateTime}
where type_value = #{body.typeValue}
  and tenant_id = #{body.tenantId}
  and industry_code = #{body.industryCode}
  and delete_flag = '0'
